import{_ as t}from"./chunks/ugso_callmebot_signal_action.CmvTIPHh.js";import{_ as a,o,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const s="/assets/callmebot-signal/en.png",f=JSON.parse('{"title":"CallMeBot Signal","description":"Signal text messages from Home Assistant with recipient profiles and Blockly.","frontmatter":{"title":"CallMeBot Signal","description":"Signal text messages from Home Assistant with recipient profiles and Blockly."},"headers":[],"relativePath":"en/projects/callmebot-signal/index.md","filePath":"en/projects/callmebot-signal/index.md","lastUpdated":1792857501000}'),n={name:"en/projects/callmebot-signal/index.md"};function l(c,e,d,p,u,g){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="callmebot-signal" tabindex="-1">CallMeBot Signal <a class="header-anchor" href="#callmebot-signal" aria-label="Permalink to &quot;CallMeBot Signal&quot;">​</a></h1><p>Beta <strong>HA app 0.1.2</strong> in the <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot_signal" target="_blank" rel="noreferrer">shared Blocks for HA repository</a>. Complete <strong>DE/EN/FR</strong>, system language and light/dark/system appearance. Original UGSo implementation inspired by <a href="https://github.com/derAlff/ioBroker.signal-cmb" target="_blank" rel="noreferrer">ioBroker.signal-cmb</a>.</p><p><img src="'+s+'" alt="Signal interface in English"></p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Add <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> to the HA app store and install <strong>CallMeBot Signal</strong>.</li><li>Configure HA MQTT, start the app and open its Ingress UI. Supervisor MQTT credentials take priority; app options are the fallback.</li><li>Use the current bot contact from the <a href="https://www.callmebot.com/blog/free-api-signal-send-messages/" target="_blank" rel="noreferrer">official Signal activation guide</a>. Send its activation phrase in <strong>Signal</strong> and wait for your <strong>Signal API key</strong>.</li><li>Save a profile ID, display name, your international phone number <strong>with +</strong> or <strong>Signal UUID</strong>, and matching key. When your number is hidden, the bot may provide a UUID. Copy the recipient value from the activation link unchanged.</li><li>Choose a default profile. “Send message” really sends to the selected saved profile.</li></ol><p>WhatsApp keys do not work for Signal. Both apps can run together with isolated profiles, MQTT topics, client IDs and diagnostic entities. The <a href="./../callmebot/">WhatsApp app</a> retains its existing technical IDs.</p><h2 id="blockly-and-profile-selection" tabindex="-1">Blockly and profile selection <a class="header-anchor" href="#blockly-and-profile-selection" aria-label="Permalink to &quot;Blockly and profile selection&quot;">​</a></h2><p>Since <strong>Blocks for HA 0.1.50</strong>: <strong>Messages → Signal · CallMeBot</strong>.</p><p><img src="'+t+'" alt="Signal block"></p><p>Click the profile field, search by name/ID and select. Empty uses the default recipient. The display name is shown; the profile ID is stored. Connect text, a variable or Jinja as the message. Logging: errors only, none or info. The block generates native <code>mqtt.publish</code>; JSON is serialized after template evaluation.</p><p>The app publishes a catalog on <code>ugso/callmebot_signal/profiles</code> and the MQTT discovery diagnostic entity <strong><code>sensor.ugso_callmebot_signal_profiles</code></strong>. State: profile count. Attributes: IDs, names, default and source marker, <strong>no recipient, message or key</strong>. Blocks uses the source marker even if the entity is renamed. Standard discovery prefix: <code>homeassistant</code>.</p><p>Without a connection, enter the profile ID manually or leave it empty. Invalid/deleted IDs are never replaced automatically. JSON projects retain the dedicated block; YAML import displays the send as a general HA/MQTT action.</p><h2 id="protocol-and-limits" tabindex="-1">Protocol and limits <a class="header-anchor" href="#protocol-and-limits" aria-label="Permalink to &quot;Protocol and limits&quot;">​</a></h2><ul><li>Send: <code>ugso/callmebot_signal/send</code>, QoS 0, <strong>retain false</strong>.</li><li>Example: <code>{&quot;profile&quot;:&quot;default&quot;,&quot;message&quot;:&quot;Hello from HA&quot;,&quot;loglevel&quot;:&quot;errors&quot;}</code>. Empty profile uses the default recipient.</li><li>Result: <code>ugso/callmebot_signal/result</code>, not retained, profile, request ID, status and time only.</li><li>Catalog and availability: <code>ugso/callmebot_signal/profiles</code> and <code>ugso/callmebot_signal/availability</code>, retained. Availability reflects the broker connection.</li><li>Up to 16 profiles, 4000 characters, queue of 20, at least 10 seconds between attempts per profile. Faster commands are rejected.</li><li>Optional <code>request_id</code>: one-hour deduplication, up to 1000 IDs. No automatic retries/replay after restart; retained commands are rejected.</li><li>One Signal app instance per broker. Restrict write access to command topics. External MQTT TLS configuration is not included.</li></ul><p>This app sends <strong>text messages to your own activated recipients</strong>. Images, groups and replies are not implemented. <code>accepted</code> confirms API acceptance only. Recipient, key and message are sent over HTTPS to <code>https://signal.callmebot.com/signal/send.php</code>.</p><p>Keys stay in the private backend file <code>/data/profiles.json</code>, are never returned to browsers/MQTT/Blockly and are not logged. The file is not encrypted and is included in HA backups; protect backups accordingly.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Backend, UUID/number validation, MQTT protocol, Blockly/Jinja export, DE/EN/FR and mobile layout are verified with test data. Real Signal delivery and HA Supervisor installation require your own setup. Automated tests never send real messages.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot_signal" target="_blank" rel="noreferrer">Source</a> · Apache-2.0 · Independent community project.</p><h2 id="beta-history-profile-backup-and-mqtt-tls" tabindex="-1">Beta: history, profile backup and MQTT TLS <a class="header-anchor" href="#beta-history-profile-backup-and-mqtt-tls" aria-label="Permalink to &quot;Beta: history, profile backup and MQTT TLS&quot;">​</a></h2><p>History persists up to 200 entries with timestamp, profile ID, source and result. Filter by profile/error status and explicitly confirm clearing. It contains no messages, numbers, API keys or request IDs. Accepted still means provider acceptance, not confirmed delivery. A storage error never causes automatic resending.</p><p>Profile backups encrypt numbers, API keys and the default profile using AES-GCM and a password-derived key (scrypt). Choose at least 12 characters and keep the password separately; it is not stored. Restoration requires it, explicit confirmation and valid authenticated content. Wrong passwords, damaged files or backups from the other CallMeBot app leave profiles untouched. Pending sends block restoration. MQTT credentials and history are excluded; use a full HA app backup for those.</p><p>Automatic HA broker selection remains the existing default. Disable it to configure an external host, port, username and password. TLS always checks certificates and hostname; custom PEM CA and client certificate/key uploads are supported. Choose the broker TLS port, often 8883. Empty secret fields preserve saved values. HA/Blocks must use this broker or forward send/result/profile/discovery topics between brokers; this is not an automatic broker bridge.</p><p>Existing profiles.json, recipient keys, MQTT topics and entity IDs remain unchanged. History uses /data/history.json; explicitly saved MQTT settings use /data/mqtt.json. No automatic configuration rewrite. All new UI labels support DE/EN/FR.</p><p>Beta is displayed in the UI and description. HA has no native beta stage, so the valid experimental configuration stage remains. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">HA configuration</a>.</p>',25)])])}const b=a(n,[["render",l]]);export{f as __pageData,b as default};
